graphql.query:
query Vessels($mmsi: [MMSI!], $first: Int) {
  vessels(mmsi: $mmsi, first: $first) {
    pageInfo { hasNextPage endCursor }
    totalCount { relation value }
    nodes {
      id
      updateTimestamp
      staticData { name mmsi imo callsign flag shipType aisClass dimensions { length width } }
      lastPositionUpdate { latitude longitude speed course heading collectionType timestamp }
      currentVoyage { destination draught eta matchedPort { port { name unlocode } } timestamp }
    }
  }
}

query VesselsInAOI($aoi: AreaOfInterest, $shipType: [ShipType!], $first: Int) {
  vessels(areaOfInterest: $aoi, shipType: $shipType, first: $first) {
    pageInfo { hasNextPage endCursor }
    nodes {
      staticData { name mmsi shipType }
      lastPositionUpdate { latitude longitude timestamp collectionType }
    }
  }
}

query Messages($mmsi: [MMSI!], $range: TimeRange, $first: Int) {
  messages(mmsi: $mmsi, receivedTime: $range, first: $first) {
    pageInfo { hasNextPage endCursor }
    nodes { mmsi msgType latitude longitude speed course timestamp collectionType }
  }
}

query PortEventsByVessel($mmsi: MMSI, $first: Int) {
  portEventsByVessel(mmsi: $mmsi, first: $first) {
    pageInfo { hasNextPage endCursor }
    nodes { id eventType timestamp port { name unlocode } }
  }
}

query Port($unlocode: UNLOCODE!) {
  port(unlocode: $unlocode) {
    name
    unlocode
    centerPoint { latitude longitude }
  }
}

query MatchedPort($text: String!) {
  matchedPort(text: $text) {
    matchScore
    port { name unlocode centerPoint { latitude longitude } }
  }
}

query PredictedRoute($origin: RoutePoint!, $destination: RoutePoint!, $vessel: MMSI!) {
  predictedVesselRoute(origin: $origin, destination: $destination, vessel: $vessel) {
    distance
    eta
    durationHours
    route
  }
}
